// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal token-like callee that always succeeds for transferFrom calls
    contract TokenLike {
        event TransferFromCalled(address from, address to, uint256 v);
        // mimic ERC20 transferFrom signature
        function transferFrom(address from, address to, uint256 v) external returns (bool) {
            emit TransferFromCalled(from, to, v);
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzz the contract_address (we'll deploy a TokenLike and pass its address),
    // fuzz an array length and values. We cannot fuzz addresses to have code, so
    // instead we deploy a TokenLike and still fuzz the values and lengths.
    function testFuzz_property(uint256 len, uint256 seed) public {
        // keep len within reasonable bounds but allow 1..10 to be wide
        uint256 n = bound(len, 1, 10);

        // deploy adversarial helper that succeeds on transferFrom (non-reverting)
        TokenLike helper = new TokenLike();
        address contract_address = address(helper);

        // build tos and vs arrays deterministically from seed so fuzzer controls them
        address[] memory tos = new address[](n);
        uint[] memory vs = new uint[](n);
        for (uint i = 0; i < n; i++) {
            // derive pseudo-random addresses and amounts from seed & i
            // use address(uint160(...)) to convert
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, "a")))));
            vs[i] = uint256(keccak256(abi.encodePacked(seed, i, "v"))) % (2**128);
            // ensure non-zero amounts to keep inputs admissible
            if (vs[i] == 0) { vs[i] = 1; }
        }

        // Now call transfer and capture its returned boolean via try/catch.
        // The reference returns true on success; the mutant returns false.
        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, mark as false (but for our helper it shouldn't)
            ok = false;
        }

        // General property: for any admissible inputs (valid address and non-empty matching arrays),
        // the reference contract returns true on successful completion. We assert that observed return is true.
        // This will pass on the reference and fail on the mutant for some inputs (the successful ones).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: an address for the callee (we will deploy a helper and pass its address),
    // and a small length for arrays and an example amount — we let tos/vs be built inside test from the fuzzed uint
    function testFuzz_property(uint8 len, uint256 amt) public {
        // keep len in a reasonable non-zero range to be admissible
        uint256 n = bound(len, 1, 8);
        // ensure amount non-zero to be realistic but allow zero as well
        uint256 value = amt;

        // deploy a well-behaved helper that implements transferFrom and always returns true (does not revert)
        GoodCallee helper = new GoodCallee();

        // build tos and vs arrays of length n
        address[] memory tos = new address[](n);
        uint[] memory vs = new uint[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp, value)))));
            vs[i] = value + i;
        }

        // call transfer and capture whether it returns (non-revert) and returned value
        bool ok;
        bool ret;
        try c.transfer(address(helper), tos, vs) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // GENERAL PROPERTY (single assert): For the correct C, if the call did not revert (ok==true),
        // then the returned value must be true. The mutant returns false for successful executions.
        assertTrue(!ok || ret == true);
    }
}

// Minimal helper that accepts transferFrom calls and returns true (does not revert)
contract GoodCallee {
    // mimic ERC20 transferFrom signature
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept low-level calls using selector too
    fallback() external payable {
        // do nothing, just return success
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an address for the callee contract and two arrays lengths/content
    // We fuzz a single uint8 len and a uint256 value to populate arrays; the adversarial callee
    // will implement transferFrom and always succeed so the reference returns true for all admissible inputs
    // while the mutant returns false for some inputs (it inverts the return boolean).
    function testFuzz_property(address contract_address, uint8 len, uint256 v) public {
        // admissible domain: contract_address must be non-zero and not the C contract itself
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        // keep length at least 1 because C requires tos.length>0 and vs.length>0
        uint256 l = bound(len, 1, 10); // keep arrays reasonably small for gas

        // Deploy a simple helper at the given address? We cannot deploy at arbitrary address,
        // so instead deploy our helper and require fuzzed contract_address equals helper's address.
        // To allow fuzzing, we accept any input address but route through a deployed helper; the
        // admissible domain then requires the fuzzed address equals the deployed helper's address.
        // Deploy helper that implements transferFrom and always returns true (non-reverting).
        HelperSuccess h = new HelperSuccess();
        // require the fuzzer to pick the helper's address so the call goes to a contract that responds
        vm.assume(contract_address == address(h));

        // build tos and vs arrays of length l, fill tos with arbitrary addresses (use address(this))
        address[] memory tos = new address[](l);
        uint[] memory vs = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(this);
            // vary amounts using the fuzzed v and index
            vs[i] = v + i;
        }

        // Now call transfer and capture its boolean return using try/catch via low-level call to read returned bool.
        // Because transfer is external public, call it directly and get the returned bool via try/catch and ABI decode
        bool ok;
        try c.transfer(address(h), tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert because HelperSuccess always returns success from transferFrom
            ok = false;
        }

        // The universal property: for every admissible input (we constrained inputs above), reference C returns true.
        // The mutant inverts final return and thus will make ok == false for some admissible inputs; so assertTrue on ok
        assertTrue(ok);
    }
}

// minimal helper that implements transferFrom signature and always succeeds (non-reverting)
contract HelperSuccess {
    // implement the selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: contract address (as an address), arrays of tos and vs lengths/content
    function testFuzz_property(address contractAddr, address[] memory tos, uint256[] memory vs) public {
        // 1. admissible domain: contractAddr must be non-zero and not the contract itself
        vm.assume(contractAddr != address(0));
        vm.assume(contractAddr != address(c));
        // require non-empty equal-length arrays
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // 2. deploy an adversarial helper at contractAddr if it's an EOA (fuzzed address);
        // If contractAddr is not a contract, deploy a simple callee and use its address instead.
        // We cannot change the fuzzed contractAddr variable itself (it's a parameter), but we can
        // ensure that the address we pass to c.transfer is a contract that will succeed on calls.

        // If the fuzzed address already has code, we will use it directly by calling c.transfer with it.
        // However in Foundry fuzzing environment the fuzzed address is typically an EOA (no code), so to
        // keep the domain wide and still ensure the low-level calls succeed we deploy a simple SuccessCallee
        // and use its address for the call. This still leaves tos/vs fuzzed so the property remains general.

        // deploy success callee and use its address
        SuccessCallee succ = new SuccessCallee();
        address calleeAddr = address(succ);

        // Prepare tos and vs so that each tos[i] is some address (they can be arbitrary, using fuzzed values)
        // ensure that none of tos equals address(0) to avoid any external semantics outside c.transfer
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        // 3. Call c.transfer and capture its boolean success via try/catch to observe return value
        bool ok;
        try c.transfer(calleeAddr, tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, set ok = false
            ok = false;
        }

        // 4. Assert the universal property: for all admissible inputs the reference returns true.
        // This will pass on the reference implementation (which returns true when calls succeed),
        // and fail on the mutant (which returns !true -> false) for some inputs.
        assertTrue(ok);
    }
}

// Minimal helper: always returns success for transferFrom selector. It simply returns true from any call.
contract SuccessCallee {
    fallback() external payable returns (bytes memory) {
        // mimic a successful ERC20-like transferFrom by returning true (ABI-encoded)
        bytes memory ret = abi.encode(true);
        return ret;
    }
}
